def design(xy, degree):
 xy=np.asarray(xy,dtype=float); x=(xy[:,0]-900)/1000; y=(xy[:,1]-900)/1000
 return np.column_stack([np.ones(len(x)),x,y]+([x*x,x*y,y*y] if degree==2 else []))
def km_error(pred,true):
 d=np.asarray(pred)-np.asarray(true)
 return np.sqrt((d[:,0]*111.32*np.cos(np.radians(np.asarray(true)[:,1])))**2+(d[:,1]*111.32)**2)
def registration(sheet):
 arr=CONTROLS[sheet]; xy=np.array([v[1:3] for v in arr]); ll=np.array([v[3:5] for v in arr])
 candidates=[]
 for degree in (1,2):
  a=design(xy,degree); coeff=np.linalg.lstsq(a,ll,rcond=None)[0]; fit=a@coeff
  loo=[]
  for i in range(len(arr)):
   mask=np.arange(len(arr))!=i
   loo.append(a[i]@np.linalg.lstsq(a[mask],ll[mask],rcond=None)[0])
  err=km_error(loo,ll)
  candidates.append((float(np.sqrt(np.mean(err**2))),degree,coeff,err,km_error(fit,ll)))
 best=min(candidates,key=lambda v:v[0]); rmse,degree,coeff,loo,fit=best
 projected=None
 projection_comparison={}
 for projection in ('lcc','aea'):
  crs=f'+proj={projection} +lat_1=25 +lat_2=33 +lat_0=28 +lon_0=115 +datum=WGS84 +units=m +no_defs'
  forward=Transformer.from_crs('EPSG:4326',crs,always_xy=True)
  inverse=Transformer.from_crs(crs,'EPSG:4326',always_xy=True)
  target=np.array(forward.transform(ll[:,0],ll[:,1])).T;a=design(xy,1)
  c=np.linalg.lstsq(a,target,rcond=None)[0];pred=[]
  for i in range(len(arr)):
   mask=np.arange(len(arr))!=i
   q=a[i]@np.linalg.lstsq(a[mask],target[mask],rcond=None)[0]
   pred.append(inverse.transform(*q))
  err=km_error(pred,ll);score=float(np.sqrt(np.mean(err**2)))
  projection_comparison[projection]=round(score,3)
  if score<rmse:
   q=a@c;fit_ll=np.array(inverse.transform(q[:,0],q[:,1])).T
   rmse,degree,coeff,loo,fit=score,1,c,err,km_error(fit_ll,ll)
   projected=(crs,inverse)
 meta=dict(method=('sheet-specific affine to empirical '+projected[0].split()[0][6:]+' projection' if projected else ('sheet-specific second-order polynomial' if degree==2 else 'sheet-specific affine')),
  coordinateReferenceSystem='EPSG:4326',controlPointCount=len(arr),
  looRMSEKm=round(rmse,3),looMaximumKm=round(float(max(loo)),3),
  inSampleRMSEKm=round(float(np.sqrt(np.mean(fit**2))),3),
  candidateLooRMSEKm={str(v[1]):round(v[0],3) for v in candidates},
  projectedAffineCandidateLooRMSEKm=projection_comparison,
  fittedCoordinateCRS=projected[0] if projected else 'EPSG:4326',
  projectionNote='经验配准中介；不代表已识别地图集原始投影',
  originalImageSize=list(ORIGINAL[sheet]),digitizingCanvasSize=list(CANVAS[sheet]),
  coefficients=coeff.tolist(),normalization='x=(pixelX-900)/1000; y=(pixelY-900)/1000',
  controls=[dict(name=v[0],pixel=list(v[1:3]),longitude=v[3],latitude=v[4],looErrorKm=round(float(loo[i]),3)) for i,v in enumerate(arr)])
 def transform(p):
  q=design(p,degree)@coeff
  return np.array(projected[1].transform(q[:,0],q[:,1])).T if projected else q
 return transform,meta

