def main():
 import importlib.util
 spec=importlib.util.spec_from_file_location('xiang_refine',ROOT/'scripts/refine-xiang.py')
 module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
 module.update_regions(REGIONS)
 fits={s:registration(s) for s in CONTROLS}; features=[]
 for r in REGIONS:
  r=r.copy(); p=r.pop('points'); holes=r.pop('holes'); extra_parts=r.pop('extraParts',[]); s=r['source']; fn,meta=fits[s]
  rings=[]
  for j,ring in enumerate([p]+holes):
   if ring[0]!=ring[-1]: ring=ring+[ring[0]]
   geo=fn(ring).tolist()
   signed=sum(a[0]*b[1]-b[0]*a[1] for a,b in zip(geo,geo[1:]))
   if (j==0 and signed<0) or (j>0 and signed>0): geo.reverse()
   rings.append([[round(x,6),round(y,6)] for x,y in geo])
  cw,ch=CANVAS[s]; ow,oh=ORIGINAL[s]
  r.update(method='manual-source-pixel-boundary-trace + '+meta['method'],reviewStatus='approximate-traced',
   placeExamples=PLACE_EXAMPLES.get(r['id'],[]),humanLabel='、'.join(PLACE_EXAMPLES.get(r['id'],[])[:2])+'一带',
   sourceBoundary=[[round(x*ow/cw,2),round(y*oh/ch,2)] for x,y in p+[p[0]]],
   sourceHoles=[[[round(x*ow/cw,2),round(y*oh/ch,2)] for x,y in h+[h[0]]] for h in holes],
   sourceParts=[dict(outer=[[round(x*ow/cw,2),round(y*oh/ch,2)] for x,y in h+[h[0]]],holes=[]) for h in [p]+extra_parts],
   sourceImageSize=[ow,oh],digitizingCanvasSize=[cw,ch],registrationRMSEKm=meta['looRMSEKm'],
   registrationTrainingRMSEKm=meta['inSampleRMSEKm'],
   measurementStatus='no-area-level-mutual-intelligibility-measurement',
   evidenceNote=(r['evidenceNote']+' ' if r['evidenceNote'] else '')+'分类和轮廓依据所提供地图集 '+s+' 图；互通研究必须按实际调查点和任务另行匹配，未实测不得显示区域互通率。')
  geometry=shape(dict(type='Polygon',coordinates=rings))
  source_geometry=make_valid(shape(dict(type='Polygon',coordinates=[p+[p[0]]]+[h+[h[0]] for h in holes])))
  if extra_parts:
   extra_geometries=[shape(dict(type='Polygon',coordinates=[fn(part+[part[0]]).tolist()])) for part in extra_parts]
   geometry=unary_union([make_valid(geometry)]+[make_valid(g) for g in extra_geometries])
   source_geometry=unary_union([source_geometry]+[make_valid(shape(dict(type='Polygon',coordinates=[h+[h[0]]]))) for h in extra_parts])
  if r.get('sourceExclusions'):
   for excluded_id in r['sourceExclusions']:
    excluded=next(q for q in REGIONS if q['id']==excluded_id)
    assert excluded['source']==s
    for part in [excluded['points']]+excluded.get('extraParts',[]):
     geometry=make_valid(geometry).difference(make_valid(shape(dict(type='Polygon',coordinates=[fn(part+[part[0]]).tolist()]))))
     source_geometry=source_geometry.difference(make_valid(shape(dict(type='Polygon',coordinates=[part+[part[0]]]))))
  if not geometry.is_valid:
   # A source ring touching itself at the 铜鼓 enclave is split into a true
   # interior ring. No raster labels, settlement circles or admin polygons fill it.
   geometry=make_valid(geometry)
   r['topologyRepair']='source self-touch converted to an interior ring with shapely.make_valid'
  refined=r.pop('refinedSourceParts',None)
  if refined:
   source_geometry=unary_union([shape(dict(type='Polygon',coordinates=[q['outer']]+q['holes'])) for q in refined])
   geometry=unary_union([shape(dict(type='Polygon',coordinates=[fn(ring).tolist() for ring in [q['outer']]+q['holes']])) for q in refined])
   r['method']='reviewed B11 source-colour contours + shared texture boundaries + '+meta['method']
  geometry=polygonal(geometry);source_geometry=polygonal(source_geometry)
  assert geometry.is_valid and geometry.geom_type in ('Polygon','MultiPolygon') and geometry.area>0, r['id']
  source_polygons=list(source_geometry.geoms) if source_geometry.geom_type=='MultiPolygon' else [source_geometry]
  def native(ring):return [[round(x*ow/cw,2),round(y*oh/ch,2)] for x,y in ring]
  r['sourceParts']=[dict(outer=native(g.exterior.coords),holes=[native(h.coords) for h in g.interiors]) for g in source_polygons]
  if r['id']=='wu-taihu-yongjiang':
   r['method']+='; reviewed raster colour contours for 20 offshore parts'
   r['evidenceNote']=r['evidenceNote'].replace('沿海仅绘主体轮廓；舟山等岛屿另待逐岛核对，不能解读为海域或岛屿完整覆盖。','已补舟山、岱山、大衢山及周边20块可辨橙色海岛图斑；按原图橙色填纹提取并逐块叠图复查，三角方言点符号已排除。微小灰色岛礁不猜测分类。')
  if r['id']=='gan-huaiyue':r['method']='reviewed source-pixel pink-fill segmentation + '+meta['method']
  if r['id']=='xiang-loushao':
   r['evidenceNote']+=' 湘西北边缘仍为近似描绘，不能据此判断具体村落。'
  if r['id']=='wu-taihu-suhujia':
   r['evidenceNote']=r['evidenceNote'].replace('本要素为苏沪嘉小片南岸主体；长江北岸与崇明等离岛未在本要素中扩张。','已补长江北岸、崇明、长兴与横沙等原图可辨主体，离散部件按原图分别描绘。')
  if r['id']=='gan-dongsui':
   r['evidenceNote']=r['evidenceNote'].replace('洞绥片南部独立图斑；北部洪江—溆浦小图斑尚未并入。','已补洞绥片南北两块原图主体。')
  if r['id']=='xiang-jixu':
   r['evidenceNote']=r['evidenceNote'].replace('吉溆片西北主体；乡话独立范围由东缘避让，南段与娄邵片过渡仍待精描。','已补乡话两侧吉溆片主体；与洞绥片采用同图源界避让，乡话不归入湘语。')
  features.append(dict(type='Feature',properties=r,geometry=mapping(geometry)))
 output=ROOT/'dist/data'; output.mkdir(parents=True,exist_ok=True)
 (output/'regions-wu-gan.geojson').write_text(json.dumps(dict(type='FeatureCollection',features=features),ensure_ascii=False,separators=(',',':')),encoding='utf-8')
 overlaps=[]
 for i,a in enumerate(features):
  for b in features[i+1:]:
   ga,gb=shape(a['geometry']),shape(b['geometry']);area=ga.intersection(gb).area
   fraction=area/min(ga.area,gb.area)
   if fraction>.01:overlaps.append(dict(a=a['properties']['id'],b=b['properties']['id'],fractionOfSmaller=round(fraction,5),sameSource=a['properties']['source']==b['properties']['source'],action='保留两张原图界线与配准差异供复核；未按行政线或简单优先级裁切'))
 metadata=dict(version=2,source='用户提供《中国语言地图集》B9、B10、B11扫描图',featureCount=len(features),
  registration={s:m for s,(_,m) in fits.items()},
  interpretation='手工描绘的近似区域；控制点留一误差是配准诊断，不是方言边界位置精度。',
  legendCoverage={'吴语太湖片':['毗陵小片','苏沪嘉小片','苕溪小片','杭州小片','临绍小片','甬江小片'],'吴语宣州片':['太高小片','铜泾小片','石陵小片'],'吴语处衢片':['龙衢小片','处州小片'],'吴语其他片':['婺州片','台州片','瓯江片'],'徽语':['旌占片','绩歙片','休黟片','祁德片','严州片'],'赣语':['昌靖片','宜浏片','吉茶片','抚广片','鹰弋片','大通片','耒资片','洞绥片','怀岳片'],'湘语':['长益片','娄邵片','吉溆片']},
  legendLeafCoverage='所负责图例的31个叶级分类均有主体形状；不等于所有微小图斑、语言岛和海岛逐一穷尽。',
  incompleteCoverage=['B9 崇明、长兴、横沙及舟山群岛20块橙色图斑已补；微小灰色岛礁与无明确填纹的离岛不猜测分类','B10 怀岳片已按粉色填纹补齐并保留大于50工作像素的内孔；更小水域与文字造成的空洞按比例尺概化','村落级语言岛、移民语言符号与部分水域孔洞','B9/B10/B11跨图交叠仍保留来源差异，详见crossSheetOverlapAudit'],
  crossSheetOverlapAudit=overlaps,
  boundaryReview='原图人工逐点近似描绘；尚未由方言学专家复核，不可用于村落归属断言',
  researchPolicy='地理分类不等于听懂比例；仅实际调查方言点之间可匹配实验结果，未知配对明确未实测。')
 (output/'regions-wu-gan-metadata.json').write_text(json.dumps(metadata,ensure_ascii=False,indent=2),encoding='utf-8')
 print(json.dumps({'featureCount':len(features),'registration':{s:{k:v for k,v in m.items() if k in ['method','looRMSEKm','looMaximumKm','inSampleRMSEKm','candidateLooRMSEKm']} for s,(_,m) in fits.items()}},ensure_ascii=False,indent=2))
if __name__=='__main__': main()
